import{_ as n,c as t,o as a,ag as r}from"./chunks/framework.CoPVQkzc.js";const p=JSON.parse('{"title":"Open Integration Engine","description":"","frontmatter":{},"headers":[],"relativePath":"engine/index.md","filePath":"engine/index.md","lastUpdated":1755330293000}'),o={name:"engine/index.md"};function i(s,e,l,g,c,h){return a(),t("div",null,e[0]||(e[0]=[r('<h1 id="open-integration-engine" tabindex="-1">Open Integration Engine <a class="header-anchor" href="#open-integration-engine" aria-label="Permalink to &quot;Open Integration Engine&quot;">​</a></h1><p><a href="https://openintegrationengine.org" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/website-openintegrationengine.org-blue" alt="Website"></a><a href="https://discord.gg/azdehW2Zrx" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/943670759891554316?label=Join%20our%20Discord&amp;logo=discord&amp;style=flat" alt="Discord"></a><a href="https://hub.docker.com/u/openintegrationengine" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/docker-openintegrationengine-blue?logo=docker&amp;style=flat" alt="Docker"></a><a href="https://www.linkedin.com/company/open-integration-engine" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/linkedin-follow-blue?logo=linkedin&amp;style=flat" alt="LinkedIn"></a></p><h2 id="mission-statement" tabindex="-1">Mission Statement <a class="header-anchor" href="#mission-statement" aria-label="Permalink to &quot;Mission Statement&quot;">​</a></h2><p>To empower seamless healthcare interoperability through an open, community-driven integration engine that is accessible, extensible, and standards-based.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>Open Integration Engine Project</strong> is an open-source initiative committed to advancing healthcare interoperability. Building upon the foundation of <strong>Mirth Connect</strong>, a widely adopted integration engine, this project aims to provide healthcare organizations with a robust, flexible, and cost-effective solution for connecting disparate systems and facilitating efficient data exchange.</p><h2 id="why-open-integration-engine" tabindex="-1">Why Open Integration Engine? <a class="header-anchor" href="#why-open-integration-engine" aria-label="Permalink to &quot;Why Open Integration Engine?&quot;">​</a></h2><ul><li><p><strong>Open Source Advantage</strong> Transparency, innovation, and collaborative development within the healthcare IT community.</p></li><li><p><strong>Healthcare-Focused</strong> Designed to address the unique challenges of healthcare data integration, supporting standards such as HL7, FHIR, and DICOM.</p></li><li><p><strong>Extensible and Customizable</strong> Modular architecture for customization and expansion to meet evolving needs.</p></li></ul><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><ul><li><p><strong>Data Transformation and Mapping</strong> Convert between HL7, JSON, XML, and other formats to ensure cross-system compatibility.</p></li><li><p><strong>Message Routing and Filtering</strong> Route messages using flexible, rules-based logic to streamline workflows.</p></li><li><p><strong>Custom Scripting and Connectors</strong> JavaScript-based scripting and support for protocols like HTTP/S, FTP, and database connectivity.</p></li><li><p><strong>Real-Time Monitoring and Alerts</strong> Visual tools for tracking message flow, performance metrics, and setting up alerts.</p></li></ul><h2 id="who-it-s-for" tabindex="-1">Who It’s For <a class="header-anchor" href="#who-it-s-for" aria-label="Permalink to &quot;Who It’s For&quot;">​</a></h2><ul><li><strong>Integration Engineers</strong> – Looking for a flexible, open platform for managing interfaces</li><li><strong>Health IT Teams</strong> – Connecting EHRs, LIS, RIS, and other healthcare systems</li><li><strong>EHR Vendors</strong> – Enhancing interoperability within their products</li><li><strong>Researchers</strong> – Requiring reliable, standards-based integration tools</li></ul><h2 id="project-values" tabindex="-1">Project Values <a class="header-anchor" href="#project-values" aria-label="Permalink to &quot;Project Values&quot;">​</a></h2><ul><li><strong>Community-Driven Development</strong> – Innovation through global collaboration</li><li><strong>Vendor Neutrality</strong> – Free from proprietary constraints</li><li><strong>Security and Compliance</strong> – HIPAA/GDPR-compliant architecture</li></ul><h2 id="community-and-governance" tabindex="-1">Community and Governance <a class="header-anchor" href="#community-and-governance" aria-label="Permalink to &quot;Community and Governance&quot;">​</a></h2><p>Engage with the community and project through:</p><ul><li>🌐 <strong>Website</strong>: <a href="https://openintegrationengine.org" target="_blank" rel="noreferrer">openintegrationengine.org</a></li><li>💬 <strong>Discord</strong>: <a href="https://discord.gg/azdehW2Zrx" target="_blank" rel="noreferrer">Join our server</a></li><li>📂 <strong>GitHub Repo</strong>: <a href="https://github.com/OpenIntegrationEngine/engine" target="_blank" rel="noreferrer">github.com/OpenIntegrationEngine/engine</a></li><li>📥 <strong>Releases</strong>: <a href="https://github.com/OpenIntegrationEngine/engine/releases" target="_blank" rel="noreferrer">Latest Releases</a></li><li>🗳️ <strong>Governance</strong>: <a href="https://github.com/OpenIntegrationEngine/governance" target="_blank" rel="noreferrer">Governance Docs</a></li><li>🐳 <strong>Docker Hub</strong>: <a href="https://hub.docker.com/u/openintegrationengine" target="_blank" rel="noreferrer">OpenIntegrationEngine on Docker Hub</a></li><li>🔗 <strong>LinkedIn</strong>: <a href="https://www.linkedin.com/company/open-integration-engine" target="_blank" rel="noreferrer">Follow us on LinkedIn</a></li></ul><p>Governance is structured to be transparent and inclusive, with decisions made collectively to reflect the community’s best interests.</p><h2 id="history-and-roadmap" tabindex="-1">History and Roadmap <a class="header-anchor" href="#history-and-roadmap" aria-label="Permalink to &quot;History and Roadmap&quot;">​</a></h2><p>Forked from <strong>Mirth Connect</strong> following its shift to a proprietary model, this project continues the legacy of open healthcare integration.</p><h3 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h3><p><strong>Short-Term Goals</strong></p><ul><li>Stabilize codebase</li><li>Improve documentation</li><li>Expand community involvement</li></ul><p><strong>Long-Term Vision</strong></p><ul><li>Support new healthcare standards</li><li>Enhance UX/UI</li><li>Grow plugin ecosystem</li></ul><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><p>Licensed under the <strong>Mozilla Public License 2.0</strong> (MPL 2.0). See <a href="https://github.com/OpenIntegrationEngine/engine/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a> for details.</p><h2 id="acknowledgments" tabindex="-1">Acknowledgments <a class="header-anchor" href="#acknowledgments" aria-label="Permalink to &quot;Acknowledgments&quot;">​</a></h2><p>Special thanks to the original <strong>Mirth Connect</strong> team and the broader open-source healthcare integration community.</p>',29)]))}const m=n(o,[["render",i]]);export{p as __pageData,m as default};
